def build_agent(sandbox):
    CHASSIS_WIDTH = 2.0
    CHASSIS_HEIGHT = 0.8
    CHASSIS_DENSITY = 15.0

    chassis = sandbox.add_beam(x=5.0, y=1.0, width=CHASSIS_WIDTH, height=CHASSIS_HEIGHT, density=CHASSIS_DENSITY)
    sandbox.set_material_properties(chassis, restitution=0.05)

    PADDLE_WIDTH = 0.4
    PADDLE_HEIGHT = 0.6
    PADDLE_DENSITY = 10.0

    front_paddle = sandbox.add_beam(x=6.0, y=1.0, width=PADDLE_WIDTH, height=PADDLE_HEIGHT, density=PADDLE_DENSITY)
    sandbox.set_material_properties(front_paddle, restitution=0.05)
    sandbox.add_joint(chassis, front_paddle, (6.0, 1.0), type='rigid')

    back_paddle = sandbox.add_beam(x=7.0, y=1.0, width=PADDLE_WIDTH, height=PADDLE_HEIGHT, density=PADDLE_DENSITY)
    sandbox.set_material_properties(back_paddle, restitution=0.05)
    sandbox.add_joint(chassis, back_paddle, (7.0, 1.0), type='rigid')

    return chassis

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    # Calculate front of the vehicle
    front_x = agent_body.position.x + 1.0  # chassis is at x=5.0, front is x + 1.0

    target_x = 26.0

    # Check if we've reached the target
    if front_x >= target_x - 0.1:
        # Stop the vehicle by applying opposing force
        for b in sandbox.bodies:
            if b.active:
                sandbox.apply_force(b, 0, 0, step_count=step_count)
        return

    # Check if vehicle is sunk
    for b in sandbox.bodies:
        if b.active:
            lowest_y = b.position.y - b.height / 2
            if lowest_y < -0.5:
                # Vehicle is sunk
                for b2 in sandbox.bodies:
                    if b2.active:
                        sandbox.apply_force(b2, 0, 0, step_count=step_count)
                return

    MAX_THRUST = 200.0
    LIFT_FORCE = 150.0

    in_deep_channel = (16.5 <= front_x <= 19.5)

    # Find front and back paddles
    front_paddle = None
    back_paddle = None

    for b in sandbox.bodies:
        if b.active:
            if b.position.x == 6.0:
                front_paddle = b
            elif b.position.x == 7.0:
                back_paddle = b

    # Apply force to front and back paddles
    if front_paddle:
        vx = front_paddle.linearVelocity.x
        fx = MAX_THRUST
        if vx > 1.8:
            fx *= 0.1
        elif vx > 1.0:
            fx *= 0.4
        fy = 0.0
        if in_deep_channel:
            fy = LIFT_FORCE
        if step_count % 3 == 0:
            sandbox.apply_force(front_paddle, -fx, fy, step_count=step_count)

    if back_paddle:
        vx = back_paddle.linearVelocity.x
        fx = MAX_THRUST
        if vx > 1.8:
            fx *= 0.1
        elif vx > 1.0:
            fx *= 0.4
        fy = 0.0
        if in_deep_channel:
            fy = LIFT_FORCE
        if step_count % 3 == 0:
            sandbox.apply_force(back_paddle, fx, fy, step_count=step_count)
